<?php use kartik\form\ActiveForm; use yii\helpers\Html; use yii\helpers\Url; ?><div class="card card-primary card-outline mb-3"><div class="card-header"><h3 class="card-title mb-0"><?= $model->isNewRecord ? 'Form Tambah Perusahaan' : 'Form Ubah Perusahaan' ?></h3></div><?php $form=ActiveForm::begin(['options'=>['autocomplete'=>'off'],'enableClientValidation'=>true,'validateOnChange'=>true,'validateOnSubmit'=>true]); ?><div class="card-body"><div class="row"><div class="col-md-4"><?= $form->field($model,'number')->textInput(['maxlength'=>true,'autofocus'=>true,'inputmode'=>'numeric']) ?><?= $form->field($model,'phone')->textInput(['maxlength'=>true]) ?></div><div class="col-md-8"><?= $form->field($model,'name')->textInput(['maxlength'=>true]) ?><?= $form->field($model,'address')->textarea(['rows'=>3]) ?></div></div></div><div class="card-footer d-flex"><?php if(!$model->isNewRecord): ?><?= Html::a('<i class="fas fa-fw fa-arrow-left"></i> Kembali',['index'],['class'=>'btn btn-sm btn-default']) ?><?php endif; ?><div class="ml-auto"><?= Html::a('<i class="fas fa-fw fa-arrow-left"></i> Batal',$model->isNewRecord?Url::to(['index']):Url::to(['view','id'=>$model->id]),['class'=>'btn btn-sm btn-secondary mr-1']) ?><?= Html::submitButton('<i class="fas fa-fw fa-check"></i> '.($model->isNewRecord?'Simpan':'Ubah'),['class'=>'btn btn-sm btn-'.($model->isNewRecord?'success':'warning')]) ?></div></div><?php ActiveForm::end(); ?></div>
